// The HTML `title` attribute (tooltip string) shares its name with the heading slot.
// Left in the intersection, `string & ReactNode` collapses the slot to `string`, so
// consumers had to cast heading elements (BurnTok, 2026-09-27 audit). Omit it like
// Result/Card/Section already do.
export type NoticeProps = Omit<HTMLAttributes<HTMLElement>, "title"> &
  Readonly<{
    title: ReactNode;
    description?: ReactNode;
    action?: ReactNode;
    icon?: ReactNode;
    tone?: NoticeTone;
    /** Unframed status beside the result; shares Notice live-region semantics. */
    appearance?: keyof typeof noticeRecipe.appearances;
    /** Canonical layout-only placement on the root element. Controlled visual keys are excluded. */
    layoutStyle?: HjmCompositionStyleProp;
  }>;

export const Notice = forwardRef<HTMLElement, NoticeProps>(function Notice(
  {
    title,
    description,
    action,
    icon,
    tone = noticeRecipe.defaults.tone,
    appearance = noticeRecipe.defaults.appearance,
    className,
    layoutStyle,
    ...props
  },
  ref,
) {
  const urgent = tone === "danger";
  return (
    <section
      {...props}
      style={{ ...props.style, ...layoutStyle }}
      ref={ref}
      className={classNames("hjm-notice", className)}
      data-tone={tone}
      data-appearance={appearance}
      role={urgent ? "alert" : "status"}
      // A background refresh can retain content while reporting danger. Honor the
      // public HTML live-region override instead of forcing every danger to interrupt.
      aria-live={props["aria-live"] ?? (urgent ? "assertive" : "polite")}
    >
      {icon ? <div className="hjm-notice__icon" aria-hidden="true">{icon}</div> : null}
      <div className="hjm-notice__content">
        {appearance === "status" ? <Badge tone={tone} size="small">{title}</Badge> : <strong className="hjm-notice__title">{title}</strong>}
        {description ? <div className="hjm-notice__description">{description}</div> : null}
      </div>
      {action ? <div className="hjm-notice__action">{action}</div> : null}
    </section>
  );
});

type EmptyStateDensity = keyof typeof emptyStateRecipe.density;

export type EmptyStateProps = Omit<HTMLAttributes<HTMLDivElement>, "title"> &
  Readonly<{
    title: ReactNode;
    description?: ReactNode;
    action?: ReactNode;
    icon?: ReactNode;
    density?: EmptyStateDensity;
    /** Canonical layout-only placement on the root element. Controlled visual keys are excluded. */
    layoutStyle?: HjmCompositionStyleProp;
  }>;

export const EmptyState = forwardRef<HTMLDivElement, EmptyStateProps>(
  function EmptyState(
    {
      title,
      description,
      action,
      icon,
      density = emptyStateRecipe.defaults.density,
      className,
      layoutStyle,
      ...props
    },
    ref,
  ) {
    return (
      <div
        {...props}
        style={{ ...props.style, ...layoutStyle }}
        ref={ref}
        className={classNames("hjm-empty-state", className)}
        data-density={density}
        role="status"
      >
        {icon ? <div className="hjm-empty-state__icon" aria-hidden="true">{icon}</div> : null}
        <strong className="hjm-empty-state__title">{title}</strong>
        {description ? <div className="hjm-empty-state__description">{description}</div> : null}
        {action ? <div className="hjm-empty-state__action">{action}</div> : null}
      </div>
    );
  },
);

export type ResultProps = Omit<
  HTMLAttributes<HTMLDivElement>,
  "children" | "title"
> &
  ResultDescriptor &
  Readonly<{
    headingLevel?: 1 | 2;
    /** Optional product glyph; its meaning is already carried by title/status. */
    icon?: ReactNode;
    /** Canonical layout-only placement on the root element. Controlled visual keys are excluded. */
    layoutStyle?: HjmCompositionStyleProp;
  }>;

/** A terminal flow outcome. EmptyState remains reserved for fillable content. */
export const Result = forwardRef<HTMLDivElement, ResultProps>(function Result(
  {
    status,
    title,
    description,
    actions,
    headingLevel = 2,
    icon,
    className,
    role,
    layoutStyle,
    ...props
  },
  ref,
) {
  const result = resolveResultDescriptor({
    status,
    title,
    ...(description === undefined ? {} : { description }),
    ...(actions === undefined ? {} : { actions }),
  });
  const Heading = headingLevel === 1 ? "h1" : "h2";

  return (
    <div
      {...props}
      style={{ ...props.style, ...layoutStyle }}
      ref={ref}
      className={classNames("hjm-result", className)}
      data-status={result.status}
      role={role ?? (result.status === "failure" ? "alert" : "status")}
    >
      <span className="hjm-result__icon" aria-hidden="true">
        {icon ?? resultRecipe.glyphs[result.status]}
      </span>
      <Heading className="hjm-result__title">{result.title}</Heading>
      {result.description ? (
        <p className="hjm-result__description">{result.description}</p>
      ) : null}
      {result.primaryAction || result.secondaryAction ? (
        <div className="hjm-result__actions">
          {/* Button row rule (usage/components/button.md): secondary → primary, so the main action ends the row
              like Dialog footers. Until 2026-10-06 Result drew primary first, the reverse of every other action row. */}
          {result.secondaryAction ? (
            <Button
              aria-label={result.secondaryAction.accessibilityLabel}
              onClick={result.secondaryAction.onAction}
              tone="secondary"
            >
              {result.secondaryAction.label}
            </Button>
          ) : null}
          {result.primaryAction ? (
            <Button
              aria-label={result.primaryAction.accessibilityLabel}
              onClick={result.primaryAction.onAction}
            >
              {result.primaryAction.label}
            </Button>
          ) : null}
        </div>
      ) : null}
    </div>
  );
});

// Same naming contract as Native: a composition that already shows the label and value elsewhere (TargetSummary's
// Statistic) names the bar with `aria-label` alone instead of printing the copy twice (2026-10-17 composition review).
type ProgressName =
  | Readonly<{ label: ReactNode; "aria-label"?: string }>
  | Readonly<{ label?: never; "aria-label": string }>;

export type ProgressProps = Omit<
  ProgressHTMLAttributes<HTMLProgressElement>,
  "children" | "max" | "size" | "value" | "aria-label"
> &
  ProgressName &
  Readonly<{
    value?: number;
    max?: number;
    /** Equal visual units for determinate linear progress; fractions fill a partial unit. */
    segments?: number;
    valueText?: string;
    /** Hide only the visible auxiliary value when the label already contains a count; accessibility keeps its value. */
    showValue?: boolean;
    size?: ProgressSize;
    tone?: ProgressTone;
    /**
     * `circular` draws the same value as a ring. It is a shape, not a second
     * component: min/max/now, the indeterminate case and the announcement are
     * identical, so the accessibility contract stays in one place.
     */
    shape?: ProgressShape;
    /** Content inside the ring — a percentage, a count, an icon. Ignored when linear. */
    children?: ReactNode;
    /** Canonical layout-only placement on the root element. Controlled visual keys are excluded. */
    layoutStyle?: HjmCompositionStyleProp;
  }>;

export const Progress = forwardRef<HTMLProgressElement, ProgressProps>(
  function Progress(
    {
      label,
      value,
      valueText,
      segments,
      showValue = progressRecipe.defaults.showValue,
      max = progressRecipe.defaults.max,
      size = progressRecipe.defaults.size,
      tone = progressRecipe.defaults.tone,
      shape = progressRecipe.defaults.shape,
      children,
      className,
      layoutStyle,
      ...props
    },
    ref,
  ) {
    if (typeof max !== "number" || !Number.isFinite(max) || max <= 0) {
      throw new RangeError("Progress max must be a positive finite number");
    }
    if (
      value !== undefined &&
      (!Number.isFinite(value) || value < 0 || value > max)
    ) {
      throw new RangeError("Progress value must be between zero and max");
    }
    const segmentFills = resolveProgressSegments(value, max, segments, shape);
    const labelId = useId();
    // usage/components/progress.md: valueText defaults to the percentage. Only Native applied it, so the same
    // StepPlayer/ScrollProgress inputs showed "0%" on Native and nothing on Web (2026-10-17 review F N4).
    const resolvedValueText = valueText ?? (value === undefined ? undefined : `${Math.round((value / max) * 100)}%`);
    const diameter = progressRecipe.circular.sizes[size];
    const strokeWidth = progressRecipe.circular.strokeWidth[size];
    return (
      <div
        className={classNames("hjm-progress", className)}
        data-size={size}
        data-tone={tone}
        data-shape={shape}
        data-segmented={segmentFills ? "true" : undefined}
        data-state={value === undefined ? "indeterminate" : "determinate"}
        // `layoutStyle` lands on this frame, not on the native <progress> that
        // receives the rest props, so placement moves the label and bar together.
        style={shape === "circular" ? ({
          ...layoutStyle,
          "--hjm-progress-diameter": `${diameter}px`,
          "--hjm-progress-stroke": `${strokeWidth}px`,
          // Conic sweep instead of an SVG arc: the same token drives both
          // shapes and no second color pipeline appears.
          "--hjm-progress-sweep": value === undefined ? "25%" : `${(value / max) * 100}%`,
        } as CSSProperties) : layoutStyle}
      >
        {label === undefined ? null : (
          <span className="hjm-progress__copy">
            {/* Label and value use the label/caption roles, as Native Progress does; both inherited body 16 before (2026-10-17 review). */}
            <Text id={labelId} variant="label">{label}</Text>
            {showValue && resolvedValueText ? <Text variant="caption" tone="muted">{resolvedValueText}</Text> : null}
          </span>
        )}
        {shape === "circular" ? (
          <span className="hjm-progress__ring" aria-hidden="true">
            {children ? <span className="hjm-progress__ring-content">{children}</span> : null}
          </span>
        ) : null}
        {segmentFills ? <span className="hjm-progress__segments" aria-hidden="true" style={{ gap: progressRecipe.segmented.gap, height: progressRecipe.sizes[size] }}>
          {segmentFills.map((fill, index) => <span key={index}><i style={{ width: `${fill * 100}%` }} /></span>)}
        </span> : null}
        <progress
          {...props}
          ref={ref}
          className="hjm-progress__native"
          max={max}
          {...(value === undefined ? {} : { value })}
          aria-labelledby={props["aria-labelledby"] ?? (props["aria-label"] === undefined ? labelId : undefined)}
          aria-valuetext={resolvedValueText}
        />
      </div>
    );
  },
);

export { Spinner, type SpinnerProps } from "./internal/spinner.js";

type SkeletonShape = keyof typeof skeletonRecipe.shapes;

export type SkeletonProps = Omit<HTMLAttributes<HTMLSpanElement>, "children"> &
  Readonly<{
    shape?: SkeletonShape;
    animated?: boolean;
    /**
     * `text` only: draw this many lines with the last one shorter (`skeletonRecipe.lines`), so a paragraph
     * placeholder is not rebuilt from loose bars in every product. `width` sizes the whole group.
     */
    lines?: number;
    /**
     * `button` only: the Button `shape` this placeholder stands in for (default: Button's default). Products that use
     * `shape="pill"` buttons pass the same value so the placeholder matches (BurnTok, 2026-10-17).
     */
    buttonShape?: ButtonShape;
    width?: string | number;
    height?: string | number;
    /** Canonical layout-only placement on the root element. Controlled visual keys are excluded. */
    layoutStyle?: HjmCompositionStyleProp;
  }>;

export const Skeleton = forwardRef<HTMLSpanElement, SkeletonProps>(
  function Skeleton(
    {
      shape = skeletonRecipe.defaults.shape,
      animated = skeletonRecipe.defaults.animated,
      lines = skeletonRecipe.defaults.lines,
      buttonShape = buttonRecipe.defaults.shape,
      width,
      height,
      className,
      style,
      layoutStyle,
      ...props
    },
    ref,
  ) {
    const lineCount = shape === "text" ? Math.max(1, Math.floor(lines)) : 1;
    if (lineCount > 1) {
      // One pulse on the group keeps the lines in phase; the bars themselves do not animate.
      return (
        <span
          {...props}
          ref={ref}
          className={classNames("hjm-skeleton-lines", className)}
          data-animated={animated}
          aria-hidden="true"
          style={{ width, ...style, ...layoutStyle }}
        >
          {Array.from({ length: lineCount }, (_, index) => (
            <span key={index} className="hjm-skeleton" data-shape="text" data-last={index === lineCount - 1 || undefined} style={{ height }} />
          ))}
        </span>
      );
    }
    return (
      <span
        {...props}
        ref={ref}
        className={classNames("hjm-skeleton", className)}
        data-shape={shape}
        data-button-shape={shape === "button" ? buttonShape : undefined}
        data-animated={animated}
        aria-hidden="true"
        style={{ width, height, ...style, ...layoutStyle }}
      />
    );
  },
);

